#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Phone captive-portal lab (answers Q3: does the iOS CNA / Android
# CaptivePortalLogin keep our cookie, and when do phones change MAC?).
# Run as ./lab/phones/wizard.sh plain|adb from anywhere in the repo.
#
# The library reads ENV_FILE lazily inside its functions, so reassigning it here
# (after the library definitions) points ask/write_env at the lab's own .env.

MODE="${1:-}"
case "$MODE" in
  plain) PHONES=(iphone android) ;;
  adb)   PHONES=(android) ;;
  recheck) PHONES=(iphone android) ;;
  *) echo "usage: $0 plain|adb|recheck   (plain: iPhone + Android; adb: Android with adb capture; recheck: the three gaps of a plain run)" >&2; exit 2 ;;
esac

# 4 setup stages + (adb: 1) + 8 per phone (recheck: 5 iPhone + 3 Android) + summary + teardown.
TOTAL_STAGES=$((4 + 8 * ${#PHONES[@]} + 2))
[[ "$MODE" == adb ]] && TOTAL_STAGES=$((TOTAL_STAGES + 1))
[[ "$MODE" == recheck ]] && TOTAL_STAGES=$((4 + 5 + 3 + 2))

LAB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ENV_FILE="$LAB_DIR/.env"
CHR_ENV="$LAB_DIR/../chr/.env"
REPO_ROOT="$(git -C "$LAB_DIR" rev-parse --show-toplevel)"
BACKUP="$LAB_DIR/.backup-login.html"
PID_FILE="$LAB_DIR/.portal.pid"

# Values saved by earlier runs; ask() only offers them, it does not load them.
for _k in PHONE_IF AP_MODEL AP_MAC PORTAL_ADDR ORIG_LOGIN_BY; do
  printf -v "$_k" '%s' "$(_existing "$_k" || true)"
done
PORTAL_ADDR="${PORTAL_ADDR:-192.168.122.1:8080}"
PORTAL_BIND="${PORTAL_ADDR%:*}"
PORTAL_PORT="${PORTAL_ADDR##*:}"

# CHR credentials come from the CHR lab's .env. Parsed, not sourced, so a password
# with shell characters stays intact. Never printed.
for _k in CHR_PASSWORD CHR_WAN_IP; do
  _line=$(grep -E "^${_k}=" "$CHR_ENV" 2>/dev/null | tail -n1 || true)
  printf -v "$_k" '%s' "${_line#*=}"
done
export CHR_PASSWORD CHR_WAN_IP

# RUN_DIR is created at start; a second run on the same day gets -2, -3, ...
RUN_BASE="$REPO_ROOT/docs/research/results/$(date +%F)-phones-$MODE"
RUN_DIR="$RUN_BASE"
for ((_n = 2; ; _n++)); do
  [[ -e "$RUN_DIR" ]] || break
  RUN_DIR="$RUN_BASE-$_n"
done
mkdir -p "$RUN_DIR/steps"
printf 'phone\tstep\tquestion\tanswer\n' > "$RUN_DIR/answers.tsv"

ONLOGOUT=':log info ("onlogout user=" . $user . " mac=" . $"mac-address" . " cause=" . $cause)'
WG_COMMENT=openpiso-phone-portal

# ── Helpers ───────────────────────────────────────────────────────────────

vsh() { virsh -c qemu:///system "$@"; }

# rest PATH [curl args...]: call the CHR REST API on its WAN address (ether1).
rest() {
  local path="$1"; shift
  curl -s --max-time 10 -u "admin:$CHR_PASSWORD" "$@" "http://$CHR_WAN_IP/rest$path"
}

# rest_json METHOD PATH BODY: send a JSON body; warns and fails on a RouterOS error.
rest_json() {
  local out
  out=$(rest "$2" -X "$1" -H 'Content-Type: application/json' --data "$3")
  if grep -q '"error"' <<<"$out"; then warn "REST $1 $2 failed: $out"; return 1; fi
}

rest_version() {
  rest /system/resource | python3 -I -c 'import json,sys; print(json.load(sys.stdin)["version"])' 2>/dev/null
}

# pick PATH KEY VALUE FIELD: FIELD of the first entry whose KEY equals VALUE.
pick() {
  rest "$1" | python3 -I -c '
import json, sys
k, v, f = sys.argv[1:4]
for e in json.load(sys.stdin):
    if e.get(k) == v:
        print(e.get(f, ""))
        break
' "$2" "$3" "$4" 2>/dev/null || true
}

# ids_where PATH FIELD PREFIX: the .id of every entry whose FIELD starts with PREFIX.
ids_where() {
  rest "$1" | python3 -I -c '
import json, sys
f, p = sys.argv[1:3]
for e in json.load(sys.stdin):
    if e.get(f, "").startswith(p):
        print(e[".id"])
' "$2" "$3" 2>/dev/null || true
}

# rest_delete_where PATH FIELD PREFIX: delete those entries (ids like "*1" work in the URL).
rest_delete_where() {
  local id
  while IFS= read -r id; do
    if [[ -n "$id" ]]; then rest "$1/$id" -X DELETE >/dev/null; fi
  done < <(ids_where "$1" "$2" "$3")
}

# show_leases: current DHCP leases on the CHR.
show_leases() {
  rest /ip/dhcp-server/lease | python3 -I -c '
import json, sys
for e in json.load(sys.stdin):
    print("    " + "  ".join(k + "=" + str(e.get(k, "-")) for k in ("mac-address", "address", "host-name", "status")))
' 2>/dev/null || warn "could not read leases"
}

# snap STEP: save hotspot hosts/active/users and DHCP leases under RUN_DIR/steps/STEP.
snap() {
  local dir="$RUN_DIR/steps/$1"
  mkdir -p "$dir"
  rest /ip/hotspot/host > "$dir/host.json" || true
  rest /ip/hotspot/active > "$dir/active.json" || true
  rest /ip/hotspot/user > "$dir/user.json" || true
  rest /ip/dhcp-server/lease > "$dir/lease.json" || true
}

# show_since TS: compact portal.jsonl lines since TS, then the live hotspot hosts and
# active sessions (the AP's own entry is skipped when AP_MAC is known).
show_since() {
  printf '\n  %sPortal log since %s%s\n' "$BOLD" "$1" "$RESET"
  HOSTS=$(rest /ip/hotspot/host) ACTIVE=$(rest /ip/hotspot/active) \
  python3 -I - "$1" "$RUN_DIR/portal.jsonl" "$AP_MAC" <<'PY'
import json, os, sys
from datetime import datetime

since, path, ap = sys.argv[1], sys.argv[2], sys.argv[3].lower()
t0 = datetime.fromisoformat(since)
n = 0
if os.path.exists(path):
    for line in open(path):
        r = json.loads(line)
        if datetime.fromisoformat(r["ts"]) < t0:
            continue
        n += 1
        print("    {}  {:<16} mac={}  cookie={}  {}  {}".format(
            r["ts"][11:19], r["ua_class"], r.get("mac") or "-",
            "yes" if r.get("cookie_opid") else "no",
            r.get("action") or r["event"], r.get("result") or ""))
if not n:
    print("    (no portal requests)")

def show(title, raw, keys):
    print(f"  {title}:")
    try:
        rows = [e for e in json.loads(raw) if e.get("mac-address", "").lower() != ap or not ap]
    except ValueError:
        print("    (unreadable)")
        return
    for e in rows or [{}]:
        print("    " + ("  ".join(f"{k}={e.get(k, '-')}" for k in keys) if e else "(none)"))

print()
show("hotspot hosts", os.environ["HOSTS"], ["mac-address", "address"])
show("hotspot active", os.environ["ACTIVE"], ["user", "mac-address", "address", "uptime"])
PY
}

# stop_portal: kill the portal recorded in PID_FILE (only if it really is portal.py).
stop_portal() {
  local pid
  pid=$(cat "$PID_FILE" 2>/dev/null || true)
  if [[ -n "$pid" ]] && tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null | grep -q 'portal.py'; then
    kill "$pid" 2>/dev/null || true
    sleep 1
  fi
  rm -f "$PID_FILE"
}

# portal_alive: success if PID_FILE names a running portal.py.
portal_alive() {
  local pid
  pid=$(cat "$PID_FILE" 2>/dev/null || true)
  [[ -n "$pid" ]] && tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null | grep -q 'portal.py'
}

# ftp_curl curl-args...: curl against the CHR FTP service as admin.
ftp_curl() { curl -sS --max-time 20 --user "admin:$CHR_PASSWORD" "$@"; }

# ── Per-step bookkeeping ──────────────────────────────────────────────────
# step_begin PHONE STEP → step_finish → qa ... → step_end

# record PHONE STEP QUESTION ANSWER: append one row to answers.tsv.
record() {
  local a="${4//$'\t'/ }"
  printf '%s\t%s\t%s\t%s\n' "$1" "$2" "$3" "${a//$'\n'/ }" >> "$RUN_DIR/answers.tsv"
}

# step_begin PHONE STEP: start the clock and clear the phone's logcat (adb mode).
step_begin() {
  S_PHONE="$1"; S_STEP="$2"; S_ID="$1-$2"
  S_DIR="$RUN_DIR/steps/$S_ID"
  mkdir -p "$S_DIR"
  : > "$S_DIR/answers.tsv"
  S_START=$(date --iso-8601=seconds)
  if [[ "$MODE" == adb ]]; then adb logcat -c 2>/dev/null || warn "adb logcat -c failed"; fi
}

# adb_capture: screenshot, captive-portal logcat lines and the current Wi-Fi MAC; failures tolerated.
adb_capture() {
  adb exec-out screencap -p > "$S_DIR/screen.png" 2>/dev/null || true
  adb logcat -d -v time 2>/dev/null | grep -iE 'NetworkMonitor|CaptivePortal|captive|portal' > "$S_DIR/logcat.txt" || true
  adb shell ip link show wlan0 2>/dev/null | grep -o "link/ether [0-9a-f:]*" > "$S_DIR/wifi-mac.txt" || true
}

# step_finish: after the human has acted: pause, capture, snapshot, show what the router saw.
step_finish() {
  pause "${1:-Press Enter once you have done this}"
  if [[ "$MODE" == adb ]]; then adb_capture; fi
  snap "$S_ID"
  show_since "$S_START"
  printf '\n'
}

# qa "Question": ask the human, store the answer (answers.tsv + this step's tsv).
qa() {
  ask ANS "$1"
  record "$S_PHONE" "$S_STEP" "$1" "$ANS"
  printf '%s\t%s\n' "$1" "${ANS//$'\t'/ }" >> "$S_DIR/answers.tsv"
}

# step_end: write step.json (start/end window plus answers) for the summary.
step_end() {
  python3 -I - "$S_DIR" "$S_PHONE" "$S_STEP" "$S_START" "$(date --iso-8601=seconds)" <<'PY'
import csv, json, sys

d, phone, step, start, end = sys.argv[1:6]
with open(f"{d}/answers.tsv") as f:
    answers = [{"question": q, "answer": a} for q, a in csv.reader(f, delimiter="\t")]
with open(f"{d}/step.json", "w") as f:
    json.dump({"phone": phone, "step": step, "start": start, "end": end, "answers": answers}, f, indent=2)
PY
  note "Saved $S_DIR"
  pause
}

# ask_reconnect: the questions shared by the "come back" steps (d-g).
ask_reconnect() {
  qa "Popup appeared? (y/n)"
  qa "Popup said Reconnected automatically? (y/n)"
  qa "Internet works without tapping? (y/n)"
}

# wait_idle_out: poll until no p-* active entry remains (idle-timeout 2m; cap 4 min).
wait_idle_out() {
  local cap=240 i n
  for ((i = cap; i > 0; i -= 5)); do
    n=$(rest /ip/hotspot/active | python3 -I -c 'import json,sys; print(sum(e.get("user","").startswith("p-") for e in json.load(sys.stdin)))' 2>/dev/null || echo "?")
    if [[ "$n" == 0 ]]; then
      printf '\r%*s\r' 60 ''
      say "The phone's active entry is gone after $((cap - i))s."
      return
    fi
    printf '\r  waiting for idle-timeout: %s active, %3ss left ' "$n" "$i"
    sleep 5
  done
  printf '\r%*s\r' 60 ''
  warn "Still active after ${cap}s; continuing anyway."
}

# kick_session: end the phone's session by deleting every p-* active entry. This is
# what the controller does on pause or idle-out.
kick_session() {
  local n
  n=$(ids_where /ip/hotspot/active user p- | grep -c . || true)
  rest_delete_where /ip/hotspot/active user p-
  if [[ "$n" == 0 ]]; then
    warn "No p-* active entry to remove: the phone was not logged in."
  else
    say "Removed $n p-* active entry(ies): the session has ended."
  fi
}

# require_active: loop until a p-* active entry exists (the phone is logged in).
# The human can bail out with "Continue without a live session?".
require_active() {
  local out
  while true; do
    out=$(rest /ip/hotspot/active | python3 -I -c '
import json, sys
for e in json.load(sys.stdin):
    if e.get("user", "").startswith("p-"):
        print("user=" + e["user"] + "  mac=" + e.get("mac-address", "-"))
' 2>/dev/null || true)
    if [[ -n "$out" ]]; then
      say "Phone is logged in:"
      sed 's/^/    /' <<<"$out"
      return
    fi
    warn "The phone is not logged in"
    say "Open the popup / tap Connect on the phone so it logs in."
    pause "Press Enter to check again"
    if [[ -z "$(ids_where /ip/hotspot/active user p-)" ]]; then
      confirm "Continue without a live session?" && return
    fi
  done
}

# recheck_iphone: the iPhone gaps of a plain run (MAC change, forget/reboot while logged in).
recheck_iphone() {
  local phone=iphone label="iPhone"
  local priv="Settings > Wi-Fi > (i) next to openpiso-lab > Private Wi-Fi Address"

  stage "$label · a. Fixed address, join and connect"
  step_begin "$phone" r-a-connect
  step "Set Private Wi-Fi Address to Fixed ($priv)."
  step "Forget openpiso-lab if the phone has it saved (Settings > Wi-Fi > (i) next to openpiso-lab > Forget This Network)."
  step "Join openpiso-lab, tap Connect in the popup, then open a normal website."
  step_finish "Press Enter when done"
  qa "Wi-Fi Address shown under Private Wi-Fi Address?"
  qa "Page said Connected? (y/n)"
  qa "Normal website loads in the browser now? (y/n)"
  step_end

  stage "$label · b. Forget and rejoin while logged in"
  require_active
  step_begin "$phone" r-b-forget
  step "Forget openpiso-lab (Settings > Wi-Fi > (i) next to openpiso-lab > Forget This Network)."
  step "Join openpiso-lab again right away."
  step "Do not tap anything."
  step_finish "Press Enter once the phone has settled"
  ask_reconnect
  step_end

  stage "$label · c. Reboot while logged in"
  require_active
  step_begin "$phone" r-c-reboot
  step "Reboot the phone."
  step "Once it is back, make sure it joins openpiso-lab (join it by hand if needed)."
  step "Do not tap anything."
  step_finish "Press Enter once the phone has settled"
  ask_reconnect
  step_end

  stage "$label · d. Private address Off"
  step_begin "$phone" r-d-off
  step "Switch Private Wi-Fi Address to Off ($priv). iOS warns and rejoins."
  step "Do not tap Connect."
  note "The old session on the private MAC may still be active: that is expected."
  step_finish "Press Enter once the phone has settled"
  ask_reconnect
  qa "Wi-Fi Address shown now?"
  step_end

  stage "$label · e. Back to Fixed"
  step_begin "$phone" r-e-fixed
  step "Switch Private Wi-Fi Address back to Fixed ($priv)."
  step "Do not tap Connect."
  step_finish "Press Enter once the phone has settled"
  ask_reconnect
  qa "Wi-Fi Address shown now (same as step a?)"
  step_end
}

# recheck_android: the Android gaps of a plain run (forget/reboot after the session ended).
recheck_android() {
  local phone=android label="Android"
  local forget="Wi-Fi settings > openpiso-lab > Forget this network"

  stage "$label · a. Join and connect"
  step_begin "$phone" r-a-connect
  step "Forget openpiso-lab if the phone has it saved ($forget)."
  step "Join openpiso-lab."
  step "Tap Connect if the sign-in page asks (it may log in by itself), then open a normal website."
  step_finish "Press Enter when done"
  qa "Privacy setting now (randomized / device MAC)?"
  qa "Page said Connected? (y/n)"
  qa "Normal website loads in the browser now? (y/n)"
  step_end

  stage "$label · b. Session ended, forget and rejoin"
  require_active
  say "Ending the session now, like the controller does on pause or idle-out."
  kick_session
  step_begin "$phone" r-b-forget
  step "Forget openpiso-lab ($forget)."
  step "Join openpiso-lab again."
  step "Do not tap anything."
  step_finish "Press Enter once the phone has settled"
  ask_reconnect
  qa "Privacy setting after forget?"
  note "Forget may reset it to randomized: that is fine, it then also exercises the cookie rebind."
  step_end

  stage "$label · c. Session ended, reboot"
  require_active
  say "Ending the session now, like the controller does on pause or idle-out."
  kick_session
  step_begin "$phone" r-c-reboot
  step "Reboot the phone and let it rejoin openpiso-lab."
  step "Do not tap anything."
  step_finish "Press Enter once the phone has settled"
  ask_reconnect
  step_end
}

# phone_flow PHONE: stages a-h for one phone (iphone | android).
phone_flow() {
  local phone="$1" label priv
  if [[ "$phone" == iphone ]]; then
    label="iPhone"
    priv="Settings > Wi-Fi > (i) next to openpiso-lab > Private Wi-Fi Address (Off / Fixed / Rotating)"
  else
    label="Android"
    priv="Wi-Fi > openpiso-lab > Privacy (randomized MAC vs device MAC)"
  fi
  local forget="Wi-Fi settings > openpiso-lab > Forget this network"
  [[ "$phone" == iphone ]] && forget="Settings > Wi-Fi > (i) next to openpiso-lab > Forget This Network"

  stage "$label · a. Phone info"
  step_begin "$phone" a-info
  step "Forget openpiso-lab if the phone already has it saved ($forget)."
  step "Look up the private-address setting: $priv"
  step_finish "Press Enter when you have the details"
  qa "Model and OS version?"
  qa "Current private-address setting for openpiso-lab?"
  step_end

  stage "$label · b. Join"
  step_begin "$phone" b-join
  step "Join the open Wi-Fi network openpiso-lab."
  step "Watch for the captive popup (iOS sheet / Android sign-in page) and note roughly how long it takes."
  step "Do NOT tap Connect yet. Leave the popup showing."
  step_finish "Press Enter once the popup has shown up (or you gave up waiting)"
  qa "Popup appeared automatically? (y/n)"
  qa "Roughly how many seconds until it appeared?"
  qa "What did it show (New device page / blank / error)?"
  step_end

  stage "$label · c. Connect"
  step_begin "$phone" c-connect
  step "Tap Connect in the popup."
  step "Watch whether the popup says Connected and whether it closes or turns into Done by itself."
  step "Then open a normal website in the browser."
  step_finish "Press Enter when done"
  qa "Page said Connected? (y/n)"
  qa "Popup turned into Done / closed by itself? (y/n)"
  qa "Normal website loads in the browser now? (y/n)"
  step_end

  stage "$label · d. Idle out and come back"
  step_begin "$phone" d-idle
  step "Turn Wi-Fi OFF on the phone."
  pause "Press Enter once Wi-Fi is off"
  note "The user profile has idle-timeout=2m, so the CHR drops the session on its own."
  wait_idle_out
  step "Turn Wi-Fi ON again and let it rejoin openpiso-lab. Do not tap anything."
  step_finish "Press Enter once the phone has settled (popup shown or not)"
  ask_reconnect
  step_end

  stage "$label · e. Forget and rejoin"
  step_begin "$phone" e-forget
  step "Forget openpiso-lab ($forget)."
  step "Join openpiso-lab again."
  step "Do not tap anything if a popup shows up and sorts itself out."
  step_finish "Press Enter once the phone has settled"
  ask_reconnect
  step_end

  stage "$label · f. Change MAC setting"
  step_begin "$phone" f-mac
  if [[ "$phone" == iphone ]]; then
    step "Settings > Wi-Fi > (i) next to openpiso-lab > Private Wi-Fi Address: switch to a different value"
    say "  (e.g. Fixed -> Rotating, or Off -> Fixed)."
  else
    step "Wi-Fi > openpiso-lab > Privacy: switch randomized <-> device MAC"
    say "  (or per-network <-> non-persistent if your Android offers it)."
  fi
  step "Rejoin openpiso-lab if the phone did not do it by itself."
  note "The old session may still be active: this is the rebind case (old MAC removed, new MAC logged in)."
  step_finish "Press Enter once the phone has settled"
  ask_reconnect
  qa "Which setting is now active?"
  step_end

  stage "$label · g. Reboot"
  step_begin "$phone" g-reboot
  step "Reboot the phone."
  step "Once it is back, make sure it joins openpiso-lab (join it by hand if needed)."
  step_finish "Press Enter once the phone has settled"
  ask_reconnect
  step_end

  stage "$label · h. Browser check"
  step_begin "$phone" h-browser
  step "In the normal browser (Safari / Chrome, NOT the popup) open: http://$PORTAL_ADDR/"
  note "The page says whether the opid cookie came with the request. Popup and browser share it only if they share cookies."
  step_finish "Press Enter once the page has loaded"
  qa "What does the page say about the cookie?"
  step_end
}

# ── Wizard ────────────────────────────────────────────────────────────────

banner "Phone captive-portal lab ($MODE)"
note "Results for this run go to $RUN_DIR"
pause

stage "Preflight"
say "Checking the host and the CHR lab."
missing=()
cmds=(curl python3 ip ss sudo virsh)
[[ "$MODE" == adb ]] && cmds+=(adb)
for c in "${cmds[@]}"; do
  command -v "$c" >/dev/null 2>&1 || missing+=("command: $c")
done
if command -v virsh >/dev/null 2>&1; then
  [[ "$(vsh domstate chr-lab 2>/dev/null || true)" == running ]] || missing+=("VM chr-lab is not running (virsh -c qemu:///system start chr-lab)")
fi
if [[ -z "$CHR_PASSWORD" || -z "$CHR_WAN_IP" ]]; then
  missing+=("CHR_PASSWORD / CHR_WAN_IP not found in lab/chr/.env (run ./lab/chr/wizard.sh first)")
elif ! rest_version >/dev/null; then
  missing+=("REST unreachable at http://$CHR_WAN_IP/rest")
fi
host_addrs=$(ip -br addr)
if ! grep -q "[[:space:]]${PORTAL_BIND}/" <<<"$host_addrs"; then
  missing+=("$PORTAL_BIND is not an address on this host (libvirt network 'default' down?)")
elif [[ -n "$(ss -H -ltn "sport = :$PORTAL_PORT" 2>/dev/null)" ]] && ! portal_alive; then
  missing+=("port $PORTAL_PORT is already in use on this host")
fi
if (( ${#missing[@]} )); then
  for m in "${missing[@]}"; do warn "missing: $m"; done
  exit 1
fi
say "All prerequisites present. RouterOS $(rest_version), portal will listen on $PORTAL_ADDR."
note "Change the portal address by setting PORTAL_ADDR in lab/phones/.env."
pause

stage "Bridge the USB-Ethernet adapter into virbr-hs"
say "The access point plugs into this adapter; bridging it puts the AP's clients on the CHR hotspot LAN."
bridged=$(ip -br link show master virbr-hs)
if [[ -n "$PHONE_IF" ]] && grep -qE "^${PHONE_IF}[@ ]" <<<"$bridged"; then
  note "$PHONE_IF is already in virbr-hs: skipping."
else
  say "Candidate interfaces (name state mac):"
  ip -br link | awk '{n = $1; sub(/@.*/, "", n); print n, $2, $3}' \
    | grep -Ev '^(lo |virbr|vnet|docker|br-|veth|wl|waydroid)' | sed 's/^/    /' || true
  ask PHONE_IF "USB-Ethernet interface name:"
  ip link show "$PHONE_IF" >/dev/null 2>&1 || { warn "no interface called '$PHONE_IF'"; exit 1; }
  write_env PHONE_IF "$PHONE_IF"
  confirm "sudo: take $PHONE_IF away from NetworkManager and enslave it to virbr-hs?" || { warn "aborted"; exit 1; }
  if command -v nmcli >/dev/null 2>&1; then sudo nmcli device set "$PHONE_IF" managed no; fi
  sudo ip link set "$PHONE_IF" master virbr-hs
  sudo ip link set "$PHONE_IF" up
fi
printf '\n'
ip -br link show master virbr-hs
pause

stage "Access point (generic checklist)"
say "Generic recipe: works for any standalone AP (COMFAST, TP-Link EAP, ...)."
step "Power the AP."
step "Connect the AP's LAN/PoE port to the USB-Ethernet adapter (through its PoE injector if it uses one)."
step "Open the AP's web UI using the address on its label or in its manual."
step "Set its operating mode to AP / bridge (not router, gateway or NAT)."
step "Turn its DHCP server OFF."
step "Create an open SSID named openpiso-lab (no password)."
step "Turn off any built-in captive portal / authentication."
note "Client isolation can stay on."
pause "Press Enter when the AP is configured"
ask AP_MODEL "AP model and firmware version:"
write_env AP_MODEL "$AP_MODEL"
say "Current DHCP leases on the CHR:"
show_leases
note "The AP itself may take a 10.5.50.x lease; that is fine. Real verification happens when a phone joins."
ask AP_MAC "AP's own MAC if you can see it above (optional, hidden from the live host list):"
[[ -n "$AP_MAC" ]] && write_env AP_MAC "$AP_MAC"
pause

stage "Router + portal setup"
say "On the CHR this will:"
step "upload a templated hotspot/login.html (original backed up first, once)"
step "add a walled-garden rule for $PORTAL_ADDR"
step "create/update the user profile 'phone' (shared-users=1, idle-timeout=2m, on-logout logger)"
step "set hs-prof login-by to http-pap, so RouterOS's own cookie login cannot hide whether OUR cookie works"
step "delete leftover p-* hotspot users and their active entries"
say "On this host it starts portal.py in the background."
confirm "Go ahead?" || { warn "aborted"; exit 1; }

if [[ ! -f "$BACKUP" ]]; then
  ftp_curl -o "$BACKUP" "ftp://$CHR_WAN_IP/hotspot/login.html" || { warn "FTP download failed (is the ftp service enabled on the CHR?)"; rm -f "$BACKUP"; exit 1; }
  if grep -q "$WG_COMMENT" "$BACKUP"; then
    warn "The login.html on the CHR is already ours and no backup exists; refusing to back it up."
    rm -f "$BACKUP"; exit 1
  fi
  say "Backed up login.html to $BACKUP"
else
  note "Backup $BACKUP already exists: keeping it."
fi
tmp=$(mktemp)
sed "s|__PORTAL__|$PORTAL_ADDR|g" "$LAB_DIR/login.html" > "$tmp"
ftp_curl -T "$tmp" "ftp://$CHR_WAN_IP/hotspot/login.html" || { rm -f "$tmp"; warn "FTP upload failed"; exit 1; }
rm -f "$tmp"
say "Uploaded login.html (portal $PORTAL_ADDR)."

if [[ -n "$(pick /ip/hotspot/walled-garden/ip comment "$WG_COMMENT" .id)" ]]; then
  note "Walled-garden rule already present."
else
  rest_json PUT /ip/hotspot/walled-garden/ip \
    "{\"dst-address\":\"$PORTAL_BIND\",\"protocol\":\"tcp\",\"dst-port\":\"$PORTAL_PORT\",\"action\":\"accept\",\"comment\":\"$WG_COMMENT\"}"
  say "Added walled-garden rule."
fi

profile_body=$(python3 -I -c '
import json, sys
print(json.dumps({"name": "phone", "shared-users": "1", "idle-timeout": "2m",
                  "keepalive-timeout": "none", "on-logout": sys.argv[1]}))
' "$ONLOGOUT")
prof_id=$(pick /ip/hotspot/user/profile name phone .id)
if [[ -n "$prof_id" ]]; then
  rest_json PATCH "/ip/hotspot/user/profile/$prof_id" "$profile_body"
  say "Updated user profile 'phone'."
else
  rest_json PUT /ip/hotspot/user/profile "$profile_body"
  say "Created user profile 'phone'."
fi

hsprof_id=$(pick /ip/hotspot/profile name hs-prof .id)
[[ -n "$hsprof_id" ]] || { warn "server profile hs-prof not found"; exit 1; }
cur_login_by=$(pick /ip/hotspot/profile name hs-prof login-by)
if [[ "$cur_login_by" != http-pap ]]; then
  write_env ORIG_LOGIN_BY "$cur_login_by"
  rest_json PATCH "/ip/hotspot/profile/$hsprof_id" '{"login-by":"http-pap"}'
  say "hs-prof login-by: $cur_login_by -> http-pap"
else
  note "hs-prof login-by is already http-pap (original: ${ORIG_LOGIN_BY:-unknown, none saved})."
fi

rest_delete_where /ip/hotspot/active user p-
rest_delete_where /ip/hotspot/user name p-
say "Removed leftover p-* users and active entries."

stop_portal
nohup python3 -I "$LAB_DIR/portal.py" --bind "$PORTAL_BIND" --port "$PORTAL_PORT" --out "$RUN_DIR" \
  > "$RUN_DIR/portal.stderr" 2>&1 &
echo $! > "$PID_FILE"
disown
sleep 1
if curl -s --max-time 5 -o /dev/null "http://$PORTAL_ADDR/"; then
  say "Portal answers on http://$PORTAL_ADDR/ (pid $(cat "$PID_FILE"))."
else
  warn "Portal did not answer; stderr:"
  cat "$RUN_DIR/portal.stderr"
  exit 1
fi
note "That check shows up as one browser-check line in portal.jsonl."
pause

if [[ "$MODE" == adb ]]; then
  stage "adb connect"
  step "On the Android phone enable Developer options, then USB debugging."
  step "Plug it into this computer by USB and accept the 'Allow USB debugging' prompt."
  pause "Press Enter once plugged in"
  while true; do
    devs=$(adb devices)
    if awk 'NR > 1 && $2 == "device" {found = 1} END {exit !found}' <<<"$devs"; then break; fi
    echo "$devs"
    warn "No authorised device listed."
    confirm "Try again?" || exit 1
  done
  adb_info="$(adb shell getprop ro.product.manufacturer | tr -d '\r') $(adb shell getprop ro.product.model | tr -d '\r'), Android $(adb shell getprop ro.build.version.release | tr -d '\r')"
  say "Connected: $adb_info"
  record android adb-connect "Device (adb getprop)" "$adb_info"
  pause
fi

for p in "${PHONES[@]}"; do
  if [[ "$MODE" == recheck ]]; then "recheck_$p"; else phone_flow "$p"; fi
done

stage "Summary"
say "Writing results.md from answers.tsv and portal.jsonl."
python3 -I - "$RUN_DIR" "$MODE" "$(date +%F)" "$(rest_version || echo unknown)" "$AP_MODEL" <<'PY'
import csv, glob, json, os, sys
from datetime import datetime

run, mode, day, ros, ap = sys.argv[1:6]

def ts(s):
    return datetime.fromisoformat(s)

rows = list(csv.DictReader(open(f"{run}/answers.tsv"), delimiter="\t"))
log = []
if os.path.exists(f"{run}/portal.jsonl"):
    log = [json.loads(l) for l in open(f"{run}/portal.jsonl")]
steps = {}
for p in glob.glob(f"{run}/steps/*/step.json"):
    s = json.load(open(p))
    steps[(s["phone"], s["step"])] = s

out = [f"# Phone captive-portal lab results", "",
       f"- Date: {day}", f"- Mode: {mode}", f"- RouterOS: {ros}", f"- AP: {ap or 'unknown'}"]
for r in rows:
    if r["step"] in ("a-info", "adb-connect"):
        out.append(f"- {r['phone']} ({r['step']}): {r['question']} {r['answer']}")

def cell(s):
    return s.replace("|", "/") or "-"

for phone in dict.fromkeys(r["phone"] for r in rows):
    out += ["", f"## {phone}", "",
            "| step | popup? | MAC seen | opid cookie returned? | portal action | internet w/o tap? | notes |",
            "|---|---|---|---|---|---|---|"]
    for step in dict.fromkeys(r["step"] for r in rows if r["phone"] == phone):
        mine = [r for r in rows if r["phone"] == phone and r["step"] == step]
        popup = net = ""
        notes = []
        for r in mine:
            q = r["question"].lower()
            if q.startswith("popup appeared"):
                popup = r["answer"]
            elif q.startswith("internet") or q.startswith("normal website"):
                net = r["answer"]
            else:
                notes.append(f"{r['question']} {r['answer']}")
        macs, cookie, actions = [], "-", []
        win = steps.get((phone, step))
        if win:
            hits = [l for l in log if ts(win["start"]) <= ts(l["ts"]) <= ts(win["end"])]
            macs = list(dict.fromkeys(l["mac"] for l in hits if l.get("mac")))
            actions = list(dict.fromkeys(l.get("action") or l["event"] for l in hits))
            if hits:
                cookie = "yes" if any(l.get("cookie_opid") for l in hits) else "no"
        out.append("| " + " | ".join(cell(x) for x in (
            step, popup, ", ".join(macs), cookie, ", ".join(actions), net, "; ".join(notes))) + " |")

out += ["", "Findings: TODO (E/C/D labels), see raw files", "", "Raw files:",
        "- answers.tsv (every answer)", "- portal.jsonl (every portal request)",
        "- identities.json (opid -> HotSpot user)", "- portal.stderr",
        "- steps/<phone>-<step>/ (step.json, host/active/user/lease JSON, plus screen.png, logcat.txt, wifi-mac.txt in adb mode)"]
open(f"{run}/results.md", "w").write("\n".join(out) + "\n")
PY
say "Wrote $RUN_DIR/results.md"
note "Findings are left as TODO: label them E/C/D by hand from the raw files."
pause

stage "Teardown (optional)"
say "Puts the CHR and this host back as they were. Results stay in $RUN_DIR."
if confirm "Tear down the lab setup now?"; then
  stop_portal
  say "Portal stopped."
  if [[ -f "$BACKUP" ]]; then
    ftp_curl -T "$BACKUP" "ftp://$CHR_WAN_IP/hotspot/login.html" && say "login.html restored from backup." || warn "login.html restore failed"
  else
    warn "No login.html backup found; not restoring."
  fi
  if [[ -n "$ORIG_LOGIN_BY" ]]; then
    hsprof_id=$(pick /ip/hotspot/profile name hs-prof .id)
    rest_json PATCH "/ip/hotspot/profile/$hsprof_id" "{\"login-by\":\"$ORIG_LOGIN_BY\"}" && say "hs-prof login-by restored to $ORIG_LOGIN_BY."
  else
    warn "No ORIG_LOGIN_BY saved; hs-prof login-by left alone."
  fi
  rest_delete_where /ip/hotspot/walled-garden/ip comment "$WG_COMMENT"
  say "Walled-garden rule removed."
  if [[ -n "$PHONE_IF" ]]; then
    sudo ip link set "$PHONE_IF" nomaster
    if command -v nmcli >/dev/null 2>&1; then sudo nmcli device set "$PHONE_IF" managed yes; fi
    say "$PHONE_IF released from virbr-hs."
  fi
else
  note "Left as is. Stop the portal later with: kill \$(cat $PID_FILE)"
fi

finish
